import fs from 'node:fs';
import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
const packet='/workspace/.tmp/SIO173-custody01/packet-controls-bounded/oversized-trailer.tar.gz';
const old=await import(pathToFileURL('/workspace/.tmp/SIO173-custody01/before-bounds.mjs'));
const fixed=await import(pathToFileURL(process.cwd()+'/scripts/dev/sio173_evidence_packet.mjs'));
const alloc=Buffer.alloc;let requested=0;const results=[];
Buffer.alloc=function(size,...args){if(size>128*1024*1024){requested++;throw Error('TEST_ONLY_LARGE_ALLOC_INTERCEPTED');}return alloc(size,...args);};
try {
 for(const [name,module,expected,requests]of [['before',old,'TEST_ONLY_LARGE_ALLOC_INTERCEPTED',1],['after',fixed,'tar terminator bound',0]]) {
  requested=0;let message='';try{await module.loadPacket(packet);}catch(e){message=e.message;}
  assert(message.includes(expected));assert.equal(requested,requests);
  results.push({reader:name,refusal:message,large_allocation_attempts:requested,actual_large_bytes_allocated:0});
 }
}finally{Buffer.alloc=alloc;}
fs.writeFileSync('/workspace/.tmp/SIO173-custody01/trailer-bound-regression.json',JSON.stringify(results,null,2)+'\n');
console.log('BOUNDS_BEFORE_AFTER_WITHOUT_LARGE_ALLOCATION_PASS');
